#pragma once
/* ================================================================================================
 * File: builtin.h
 * Brief: Declarations for the images compiled into the ELF, under src/ps2/builtin/ (generated by
 *        src/tools/host/imgdump.cpp from id1's pak0, the same in the shareware and the registered
 *        game). They are there before any game data has been found, which is when the boot splash
 *        draws (renderer/splash_screen.h).
 *
 * This source code is released under the GNU GPL v2 license.
 * ================================================================================================ */

// gfx/palette.lmp: Quake's 256 colours as RGBA (0xAABBGGRR), index 255 transparent. Only for what
// draws before the game data is found: the game itself reads the palette out of its data, which a
// mod may change (texmgr.cpp's LoadPalette).
extern const unsigned int global_palette[256];

// gfx/qplaque.lmp: the QUAKE plaque down the left of the menus, 8-bit indices into the palette,
// with no transparent ones. The boot splash shows it, and Draw_CachePic hands the menus this copy
// rather than reading the file (draw.cpp).
extern const int qplaque_width;
extern const int qplaque_height;
extern const int qplaque_size_bytes;
extern const unsigned char qplaque_data[];
